package org.jfree.data.xy;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for XYSeries.addOrUpdate.
 */
public class XYSeries_addOrUpdate_TriageGen2Test {

    @Test(expected = IllegalArgumentException.class)
    public void testAddOrUpdateWithNullX() {
        XYSeries series = new XYSeries("Test");
        series.addOrUpdate(null, 1.0);
    }

    @Test
    public void testAddOrUpdateNewItemNoAutoSort() {
        XYSeries series = new XYSeries("Test", false);
        XYDataItem overwritten = series.addOrUpdate(1.0, 10.0);

        assertNull("Overwritten should be null for new item", overwritten);
        assertEquals("Item count should be 1", 1, series.getItemCount());
        assertEquals("X value mismatch", 1.0, series.getX(0).doubleValue(), 0.001);
        assertEquals("Y value mismatch", 10.0, series.getY(0).doubleValue(), 0.001);
    }

    @Test
    public void testAddOrUpdateNewItemWithAutoSort() {
        // Test that autoSort places item at the correct index
        XYSeries series = new XYSeries("Test", true);
        series.addOrUpdate(3.0, 30.0);
        series.addOrUpdate(1.0, 10.0);
        series.addOrUpdate(2.0, 20.0);

        assertEquals("Item count should be 3", 3, series.getItemCount());
        assertEquals("X at index 0 should be 1.0", 1.0, series.getX(0).doubleValue(), 0.001);
        assertEquals("X at index 1 should be 2.0", 2.0, series.getX(1).doubleValue(), 0.001);
        assertEquals("X at index 2 should be 3.0", 3.0, series.getX(2).doubleValue(), 0.001);
    }

    @Test
    public void testAddOrUpdateUpdateExistingNoDuplicatesAllowed() {
        XYSeries series = new XYSeries("Test", true, false);
        series.addOrUpdate(1.0, 10.0);

        XYDataItem overwritten = series.addOrUpdate(1.0, 20.0);

        assertNotNull("Should return the overwritten item", overwritten);
        assertEquals("Overwritten Y should be 10.0", 10.0, overwritten.getY().doubleValue(), 0.001);
        assertEquals("New Y should be 20.0", 1, series.getItemCount());
        assertEquals("Current Y should be 20.0", 20.0, series.getY(0).doubleValue(), 0.001);
    }

    @Test
    public void testAddOrUpdateDuplicateXAllowed() {
        XYSeries series = new XYSeries("Test", false, true);
        series.addOrUpdate(1.0, 10.0);
        XYDataItem overwritten = series.addOrUpdate(1.0, 20.0);

        assertNull("Overwritten should be null when duplicates are allowed", overwritten);
        assertEquals("Item count should be 2", 2, series.getItemCount());
        assertEquals("First Y should be 10.0", 10.0, series.getY(0).doubleValue(), 0.001);
        assertEquals("Second Y should be 20.0", 20.0, series.getY(1).doubleValue(), 0.001);
    }

    @Test
    public void testAddOrUpdateExceedMaximumItemCount() {
        XYSeries series = new XYSeries("Test");
        series.setMaximumItemCount(2);

        series.addOrUpdate(1.0, 10.0);
        series.addOrUpdate(2.0, 20.0);
        // This third addition should trigger removal of index 0
        series.addOrUpdate(3.0, 30.0);

        assertEquals("Item count should be capped at 2", 2, series.getItemCount());
        assertEquals("First item (1.0) should have been removed", 2.0, series.getX(0).doubleValue(), 0.001);
        assertEquals("Second item (3.0) should be at index 1", 3.0, series.getX(1).doubleValue(), 0.001);
    }

    @Test
    public void testAddOrUpdateWithLargeValues() {
        XYSeries series = new XYSeries("Test");
        series.addOrUpdate(Double.MAX_VALUE, Double.MIN_VALUE);
        assertEquals("X mismatch", Double.MAX_VALUE, series.getX(0).doubleValue(), 0.0);
        assertEquals("Y mismatch", Double.MIN_VALUE, series.getY(0).doubleValue(), 0.0);
    }
}
